mean-average-precision.pseudocode:
def average_precision(ranked_hits, n_relevant):
    # ranked_hits: 신뢰도순 결과의 정답 여부 목록
    # 검색 방식 AP(보간 없음)
    tp, ap = 0, 0.0
    for k, hit in enumerate(ranked_hits, start=1):
        if hit:
            tp += 1
            ap += tp / k  # 정답 위치에서의 정밀도
    return ap / n_relevant if n_relevant else 0.0

def mean_ap(per_class):  # [(ranked_hits, n_rel), ...]
    aps = [average_precision(h, n) for h, n in per_class]
    return sum(aps) / len(aps)

