classDiagram
  class Mediator {
    <<interface>>
    +notify(sender, event)
  }
  class ChatRoom {
    -users
    +notify(sender, event)
  }
  class Colleague {
    -mediator
    +send(msg)
    +receive(msg)
  }
  class User
