  Colleague <|-- User
  Colleague --> Mediator : 중재자만 참조
  ChatRoom o-- User : 동료 관리

mediator-pattern.pseudocode:
class ChatRoom:  # Mediator
    def __init__(self):
        self.users = []

    def join(self, user):
        self.users.append(user)
        user.room = self

    def notify(self, sender, msg):  # 다른 동료에게 중계
        for u in self.users:
            if u is not sender:
                u.receive(sender.name, msg)

class User:  # Colleague: 중재자만 참조
    def __init__(self, name):
        self.name = name
        self.room = None

    def send(self, msg):
        self.room.notify(self, msg)

    def receive(self, frm, msg):
        print(f'{self.name} ← {frm}: {msg}')

membership-function.pseudocode:
def triangular(x, a, b, c):  # a < b < c, 꼭짓점 b
    if x <= a or x >= c:
        return 0.0
    if x <= b:
        return (x - a) / (b - a)  # 상승 구간
    return (c - x) / (c - b)  # 하강 구간

def trapezoid(x, a, b, c, d):  # [b, c]에서 소속도 1
    if x <= a or x >= d:
        return 0.0
    if b <= x <= c:
        return 1.0
    if x < b:
        return (x - a) / (b - a)
    return (d - x) / (d - c)

# 예: 따뜻하다 = triangular(t, 15, 22, 30)

memento-pattern.diagram:
classDiagram
  class Originator {
    -state
    +save() Memento
    +restore(m)
  }
  class Memento {
    -state
    -getState()
  }
  class Caretaker {
    -history
    +backup()
    +undo()
  }
  Originator ..> Memento : 생성·복원
  Caretaker o-- Memento : 보관만(내부 접근 불가)

memento-pattern.pseudocode:
class Memento:  # 상태 스냅샷
    def __init__(self, state):
        self._state = state

class Editor:  # Originator
    def __init__(self):
        self.text = ''

    def save(self):
        return Memento(self.text)

    def restore(self, m):
        self.text = m._state  # 생성자만 내부 접근

class History:  # Caretaker: 내용은 모름
    def __init__(self, editor):
        self.editor, self.stack = editor, []

    def backup(self):
        self.stack.append(self.editor.save())

    def undo(self):
        if self.stack:
            self.editor.restore(self.stack.pop())

memoization.pseudocode:
memo = {}

def fib(n):
    if n in memo:  # 이미 계산한 부분 문제
        return memo[n]
    if n <= 1:
        result = n
    else:
        result = fib(n - 1) + fib(n - 2)
    memo[n] = result  # 결과 저장
    return result

memory-placement-strategy.pseudocode:
def choose(free, size, policy, last=0):
    # free: [(시작주소, 크기), ...] 주소순 가용 블록
    ok = [i for i, (_, s) in enumerate(free) if s >= size]
    if not ok:
        return None  # 외부 단편화로 할당 실패
    if policy == 'first':  # 처음 만나는 충분한 블록
        return ok[0]
    if policy == 'best':  # 잔여 공간 최소
        return min(ok, key=lambda i: free[i][1])
    if policy == 'worst':  # 가장 큰 블록
        return max(ok, key=lambda i: free[i][1])
    nxt = [i for i in ok if i >= last]  # next: 직전 위치부터
    return nxt[0] if nxt else ok[0]

def allocate(free, size, policy):
    i = choose(free, size, policy)
    if i is None:
        return None
    addr, s = free[i]
    if s == size:
        free.pop(i)
    else:
        free[i] = (addr + size, s - size)  # 남은 조각 유지
    return addr

merge.pseudocode:
def merge3(base, ours, theirs):  # 같은 영역 단위 비교
    if ours == theirs:
        return ours  # 동일 변경 또는 무변경
    if ours == base:
        return theirs  # 상대만 변경
    if theirs == base:
        return ours  # 나만 변경
    return conflict(ours, theirs)  # 양쪽 다르게 변경

def conflict(ours, theirs):  # 충돌 마커로 표시
    return ['<<<<<<< ours', *ours, '=======',
            *theirs, '>>>>>>> theirs']

merge-sort.pseudocode:
def merge_sort(a):
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    left = merge_sort(a[:mid])  # 분할 후 재귀 정렬
    right = merge_sort(a[mid:])
    return merge(left, right)

def merge(left, right):
    result, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:  # <= 로 안정성 유지
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])  # 남은 원소 복사
    result.extend(right[j:])
    return result

metamorphic-testing.pseudocode:
PI = 3.141592653589793

def metamorphic_test(sin_impl, inputs, eps=1e-9):
    failures = []
    for x in inputs:
        y = sin_impl(x)  # 원본 출력 (정답값 모름)
        x2 = PI - x  # MR 변환으로 후속 입력 생성
        y2 = sin_impl(x2)
        if abs(y - y2) > eps:  # MR: sin(x) = sin(π − x)
            failures.append(x)  # 관계 위반 → 결함
    return failures

